-- Curated per theme set for Brazil, the English-speaking world and Japan;
-- names, aliases and how well known each is per language as in
-- library_names.sql (A, B, C at the list's 90th, 50th, 15th percentile).
-- Ids "hand-<slug>", new works "topic:<slug>". No pictures: players add them
-- from the card. Insert only: safe to run again.

