-- Each name's other languages join its normalised aliases, as the library's
-- own rows have them.
update public.character_names n
set alias_norms = array(
  select distinct x from (
    select unnest(n.alias_norms) as x
    union select o.norm from public.character_names o
    where o.character_id = n.character_id and o.lang <> n.lang
  ) s where x <> n.norm
)
where n.character_id like 'hand-%';

-- Popularity where it was missing. Names shared with another character are
-- namesakes, checked one by one (Mordecai of Regular Show, not the Bible's).
update public.character_names n
set popularity = v.popularity
